('adm28', 'עובד/ת דנטלי לרשת מכוני צילומי שיניים סניף תל-אביב', 'עובד/ת דנטלי לרשת מכוני צילומי שיניים סניף תל-אביב למכון צילום שיניים בתל-אביב דרוש/ה עובד/ת דנטלי/ת הגדרת תפקיד: צילומי שיניים ושירות אדמיניסטרטיבי התפקיד הנו ביצוע כל סוגי הצילומים: צילום CT , צילום אורתודנטי, צילום צפלומטרי, צילום…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000265444.jpg', 18, 1138, 1, 1, 'https://www.alldent.co.il/adm28', 3, NULL, CURRENT_DATE, NOW()),
('se23', 'אחראי/ת שירות ותיאום טיפולים עם אוריינטציה מכירתית למרפאת שיניים חדשנית בתל אביב', 'אחראי/ת שירות ותיאום טיפולים עם אוריינטציה מכירתית למרפאת שיניים חדשנית בתל אביב למרפאת שיניים טכנולוגית ומתקדמת בתל אביב דרוש/ה אחראי/ת שירות ומכירות פרונטליות – לתפקיד משולב, מאתגר ובעל פוטנציאל התפתחות. התפקיד כולל ניהול תהליכי שירות…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/2146f0243cf57064edcb1b2f2a9d948ae0-6519110adea6f.jpeg', 13, 1138, 1, 1, 'https://www.alldent.co.il/se23', 3, NULL, CURRENT_DATE, NOW()),
('se208', 'מזכירה למרפאת שיניים בבאר-שבע', 'דרושה מזכירה למרפאת שיניים בבאר-שבע לרשת מרפאות שיניים בסניף באר-שבע דרוש/ה מזכיר/ה הגדרת תפקיד המזכירה למרפאת שיניים תחומי ניסיון נדרשים: שירות פרונטלי ללקוחות מרפאה, ניהול יומנים ורופא, שימור לקוחות קיימים, התנהלות מול מעבדות שיניים,…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/4322c4486297357d1ddd42b857d2ae04.jpg', 13, 131, 8, 1, 'https://www.alldent.co.il/se208', 3, NULL, CURRENT_DATE, NOW()),
('as123', 'סייעת למרפאת שיניים צעירה ודיגיטלית בתל-אביב', 'סייעת למרפאת שיניים צעירה ודיגיטלית בתל-אביב (רמת-החייל) למרפאת שיניים צעירה וייחודית תל-אביב דרוש/ה סייע/ת רופא שיניים הגדרת תפקיד: סייעת בחדר טיפולים ושירותי משרד סייעת בחדר טיפולים בתחומי טיפול מגוונים. השתלות דנטליות, כירורגיה קלה,…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/3c7d02a232e761b5a0f60ef4a354244f-db570cd7.jpg', 9, 1138, 1, 2, 'https://www.alldent.co.il/as123', 3, NULL, CURRENT_DATE, NOW()),
('se42', 'מזכירה למרפאת מומחים בתחום היישור שיניים בגבעת שמואל', 'מזכירה למרפאת שיניים אורתודונטית בגבעת שמואל למרפאת מומחים בתחום היישור שיניים בגבעת שמואל דרושה מזכיר/ה הגדרת תפקיד: מזכירה דנטלית התפקיד כולל: שירות פרונטלי ללקוחות מרפאה, ניהול יומנים ורופא, שימור לקוחות קיימים, התנהלות מול ספקים,…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/shutterstock_2136153007.jpg', 13, 262, 6, 2, 'https://www.alldent.co.il/se42', 3, NULL, CURRENT_DATE, NOW()),
('tec7', 'טכנאי/ת שיניים דיגיטלי למעבדת שיניים בבאר-שבע', 'טכנאי/ת שיניים דיגיטלי למעבדת שיניים בעיר באר-שבע ec7 למעבדת שיניים דנטלית בבאר-שבע דרוש/ה טכנאי/ת שיניים הגדרת תפקיד: טכנאי שיניים עם ידע בשיטות עבודה מסורתית ובשיטות עבודה דיגיטליות סריקות דיגיטליות, עיצוב דיגיטלי והדפסה תלת מימדית.…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/%D7%98%D7%9B%D7%A0%D7%90%D7%99+2.jpg', 11, 131, 8, 1, 'https://www.alldent.co.il/tec7', 3, NULL, CURRENT_DATE, NOW()),
('tec8', 'טכנאי/ת שיניים למעבדה בירושלים', 'ec8 טכנאי/ת שיניים למעבדת שיניים בעיר ירושלים ec8 למעבדת שיניים בעיר ירושלים דרוש/ה טכנאי/ת שיניים המעבדה מבקשת טכנאי עם ידע ויד ל: כתרים זמנים, תיקוני חרסינה ותותבות זמני קבועה ומיידית היקף מלאה, 5 ימים בשבוע ימים ושעות נדרשות: ימים…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/21img20231001wa0014-6518fefebe6fd.jpeg', 11, 474, 5, 1, 'https://www.alldent.co.il/tec8', 3, NULL, CURRENT_DATE, NOW()),
('doc42', 'דרוש אורתודנט למרפאה מתקדמת בבאר שבע', 'מומחה אורתודונט למרפאה מתקדמת בבאר שבע למרפאת שיניים מתקדמת ואיכותית בבאר שבע דרוש/ה מומחה ליישור שיניים זמני ההינה קבועה ומיידית היקף חלקית מדובר על 2 משמרות בחודש ניסיון מקצועי: רופא מומחה או מתמחה בתחום האורתודנטיה המרפאה מבקשת מומחה…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/alldent1+%2819%29.jpg', 2, 131, 8, 2, 'https://www.alldent.co.il/doc42', 3, NULL, CURRENT_DATE, NOW()),
('doc82', 'דרוש/ה רופא/ה שיניים למרפאה פרטית בשדרות', 'דרוש/ה רופא/ה שיניים למרפאה פרטית בשדרות למרפאת שיניים משפחתית בעיר שדרות דרוש/ה רופא/ה שיניים הגדרת תפקיד: רופא שיניים בחדר טיפולים מרפאה ותיקה בעלת מוניטין. במרפאה יש צוות משפחתי ונעים הכולל רופאים, מומחים, שינניות, סייעות מזכירות…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000329768.jpg', 1, 1084, 8, 2, 'https://www.alldent.co.il/doc82', 3, NULL, CURRENT_DATE, NOW()),
('doc8', 'דרוש/ה מומחה/רופא שיניים בתחום האורתודונטיה', 'מומחה / רופא שיניים בתחום האורתודונטיה לאשדוד וקרית-גת לרשת שיניים בפריסה ארצית דרוש/ה מומחה אורתודונטיה סניף קרית גת ואשדוד המרפאה מבקשת רופא מומחה או רופא שיניים בעל ניסיון רב שעוסק במגוון שיטות הטיפול האורתודונטיות זמני קבועה ומיידית…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/%D7%93%D7%A0%D7%98%D7%9C%D7%99+%D7%9C%D7%9E%D7%A9%D7%A8%D7%95%D7%AA+%2819%29.jpeg', 2, NULL, NULL, 2, 'https://www.alldent.co.il/doc8', 3, NULL, CURRENT_DATE, NOW()),
('doc7', 'דרוש/ה רופא מנוסה /מומחה אנדודונטיה בחיפה ובנהריה', 'דרוש/ה רופא מנוסה/מומחה בתחום אנדודונטיה חיפה ונהריה לרשת שיניים בפריסה ארצית דרוש/ה מומחה או רופא/ה מנוסה לטיפולי שורש. סניפים: חיפה ונהריה זמני קבועה ומיידית היקף חלקית ימים : גמיש ניסיון מקצועי: מינימום 8 שנים לרופאים ולמומחים 1 שנה…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/%D7%93%D7%A0%D7%98%D7%9C%D7%99+%D7%9C%D7%9E%D7%A9%D7%A8%D7%95%D7%AA+%2811%29.jpeg', 4, NULL, NULL, 2, 'https://www.alldent.co.il/doc7', 3, NULL, CURRENT_DATE, NOW()),
('doc27', 'דרוש/ה רופא/ה שיניים באילת', 'דרוש/ה רופא/ה שיניים כללי באילת לרשת שיניים בפריסה ארצית דרוש/ה רופא/ה שיניים כללי סניפים רלוונטים: אילת המרפאה מבקשת רופא שיניים שיודע לבצע מגוון רחב של טיפולים משמרת + טיפולי שורש + שיקום + כירורגיה קלה עדיפות לרופא נעים , נחמד ומקצועי,…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/job--2859-29-7cdb00c2.jpg', 1, 61, 8, 2, 'https://www.alldent.co.il/doc27', 3, NULL, CURRENT_DATE, NOW()),
('doc62', 'רופא/ה שיניים למרפאה פרטית ומתקדמת בבאר-שבע', 'רופא/ה שיניים למרפאה איכותית ומתקדמת בבאר-שבע למרפאת שיניים פרטית ואיכותית בבאר-שבע דרוש/ה רופא/ה שיניים הגדרת תפקיד: רופא/ה שיניים קליני וניהול מרפאה המרפאה מבקשת רופא/ה מקצועי/ת בעל נסיון מוכח של שנים רבות בתחום עם גישה עסקית עם רצון…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/360_F_545297571_AKT0Dzz8cvo76oqIP14EXTLbbSvmipdc.jpg', 1, 131, 8, 5, 'https://www.alldent.co.il/doc62', 3, NULL, CURRENT_DATE, NOW()),
('se91', 'מזכירה למרפאת שיניים איכותית בקרית מוצקין', 'דרושה מזכירה למרפאת שיניים מקצועית בקרית מוצקין דרושה מזכירה למרפאת שיניים מקצועית בקרית מוצקין. הגדרת תפקיד: מזכירה פרונטלית התפקיד כולל שירותי משרד מלאים :שירות פרונטלי ללקוחות מרפאה, ניהול יומנים ורופא, התנהלות מול מעבדות שיניים, גביית…', 'https://irp.cdn-website.com/f6084fc5/dms3rep/multi/1000265446.jpg', 13, 989, 13, 2, 'https://www.alldent.co.il/se91', 3, NULL, CURRENT_DATE, NOW()),
